-- ---------------------------------------------------------------------------
-- 041_per_lesson_quizzes.sql
-- Replaces the shared/rotating quiz bank with per-lesson question sets.
--
-- Before this migration every lesson reused one of the program few quiz
-- templates, so a "Basic Digital Literacy" quiz could ask barista questions.
-- Each lesson now carries its own questions, and the program exam samples one
-- question from evenly spaced lessons instead of the first ten of one quiz.
--
-- Only the quizzes and exams keys are touched; lessons, fees, schedules and
-- every other program field are left exactly as they are in the database.
-- ---------------------------------------------------------------------------

-- Housekeeping NC II
update public.programs
  set data = jsonb_set(data, '{quizzes}', $q$[{"id":"housekeeping-basic-l1-quiz","programId":"housekeeping","lessonId":"housekeeping-basic-l1","title":"Reading, Writing & Comprehension Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-basic-l1-quiz-q1","type":"mcq","q":"Which document would you use to formally request time off from work?","options":["Leave request form","Sales invoice","Delivery receipt","Purchase order"],"answer":"Leave request form"},{"id":"housekeeping-basic-l1-quiz-q2","type":"tf","q":"When reading workplace instructions, it is fine to skip the steps you think are unnecessary.","answer":false},{"id":"housekeeping-basic-l1-quiz-q3","type":"id","q":"The central point of a paragraph is called the ______ idea.","answer":"main"},{"id":"housekeeping-basic-l1-quiz-q4","type":"mcq","q":"Which sentence is clearest for a workplace report?","options":["Done already yesterday by me the task.","The task was completed yesterday.","Task yesterday done.","Yesterday task done by me already."],"answer":"The task was completed yesterday."}]},{"id":"housekeeping-basic-l2-quiz","programId":"housekeeping","lessonId":"housekeeping-basic-l2","title":"Basic Communication Skills Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-basic-l2-quiz-q1","type":"mcq","q":"Which behavior is the strongest sign of active listening?","options":["Interrupting to correct the speaker","Repeating back what you understood","Checking your phone","Changing the topic"],"answer":"Repeating back what you understood"},{"id":"housekeeping-basic-l2-quiz-q2","type":"tf","q":"Eye contact and posture are part of communication.","answer":true},{"id":"housekeeping-basic-l2-quiz-q3","type":"id","q":"Restating a message in your own words to confirm understanding is called ______.","answer":"paraphrasing"},{"id":"housekeeping-basic-l2-quiz-q4","type":"mcq","q":"Which tone is appropriate when writing to a customer?","options":["Sarcastic","Professional and courteous","Aggressive","Overly casual"],"answer":"Professional and courteous"}]},{"id":"housekeeping-basic-l3-quiz","programId":"housekeeping","lessonId":"housekeeping-basic-l3","title":"Basic Digital Literacy Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-basic-l3-quiz-q1","type":"mcq","q":"Which of these is an email application?","options":["Gmail","Excel","Photoshop","VLC"],"answer":"Gmail"},{"id":"housekeeping-basic-l3-quiz-q2","type":"tf","q":"A strong password should be shared with co-workers so they can open your files.","answer":false},{"id":"housekeeping-basic-l3-quiz-q3","type":"id","q":"The key combination Ctrl + C is used to ______ the selected text.","answer":"copy"},{"id":"housekeeping-basic-l3-quiz-q4","type":"mcq","q":"What should you do before opening an attachment from an unknown sender?","options":["Open it immediately","Verify the sender and scan it for malware","Forward it to all staff","Reply with your password"],"answer":"Verify the sender and scan it for malware"}]},{"id":"housekeeping-basic-l4-quiz","programId":"housekeeping","lessonId":"housekeeping-basic-l4","title":"Workplace Behavior & Professionalism Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-basic-l4-quiz-q1","type":"mcq","q":"What does punctuality at work demonstrate?","options":["Reliability and respect for others","That you are overworked","That you dislike the job","Nothing important"],"answer":"Reliability and respect for others"},{"id":"housekeeping-basic-l4-quiz-q2","type":"tf","q":"Personal social media accounts may be used to discuss confidential client information.","answer":false},{"id":"housekeeping-basic-l4-quiz-q3","type":"id","q":"The set of rules that guides acceptable behavior in the workplace is the code of ______.","answer":"conduct"},{"id":"housekeeping-basic-l4-quiz-q4","type":"mcq","q":"A colleague keeps arriving late. What is the professional response?","options":["Post about it online","Raise it with the supervisor privately","Ignore your own work","Confront them in front of clients"],"answer":"Raise it with the supervisor privately"}]},{"id":"housekeeping-common-l1-quiz","programId":"housekeeping","lessonId":"housekeeping-common-l1","title":"Workplace Communication Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-common-l1-quiz-q1","type":"mcq","q":"Which channel is best for reporting an urgent safety incident?","options":["A memo next week","A call or direct message to the supervisor","A suggestion box","A social media post"],"answer":"A call or direct message to the supervisor"},{"id":"housekeeping-common-l1-quiz-q2","type":"tf","q":"Incident reports should be written as soon as possible after the event.","answer":true},{"id":"housekeeping-common-l1-quiz-q3","type":"id","q":"The written record of what was discussed in a meeting is called the ______.","answer":"minutes"},{"id":"housekeeping-common-l1-quiz-q4","type":"mcq","q":"What is the best way to confirm instructions you received verbally?","options":["Assume you understood","Write them down and repeat them back","Wait for a written complaint","Ask a client instead"],"answer":"Write them down and repeat them back"}]},{"id":"housekeeping-common-l2-quiz","programId":"housekeeping","lessonId":"housekeeping-common-l2","title":"Workplace Safety & Emergency Procedures Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-common-l2-quiz-q1","type":"mcq","q":"What does OSH stand for?","options":["Occupational Safety and Health","Office Staff Handbook","Operational Service Hours","Organized Safety Help"],"answer":"Occupational Safety and Health"},{"id":"housekeeping-common-l2-quiz-q2","type":"tf","q":"Fire exits must be kept clear of boxes and equipment at all times.","answer":true},{"id":"housekeeping-common-l2-quiz-q3","type":"id","q":"Gear worn to protect a worker from hazards is called ______ equipment.","answer":"personal protective"},{"id":"housekeeping-common-l2-quiz-q4","type":"mcq","q":"During an earthquake while indoors you should:","options":["Run to the elevator","Duck, cover and hold","Stand near the windows","Call clients first"],"answer":"Duck, cover and hold"}]},{"id":"housekeeping-common-l3-quiz","programId":"housekeeping","lessonId":"housekeeping-common-l3","title":"Customer Service Excellence Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-common-l3-quiz-q1","type":"mcq","q":"What is the first step in handling a customer complaint?","options":["Defend the company","Listen without interrupting","Offer a refund immediately","Blame another staff member"],"answer":"Listen without interrupting"},{"id":"housekeeping-common-l3-quiz-q2","type":"tf","q":"Customer expectations are met only when the service is free of charge.","answer":false},{"id":"housekeeping-common-l3-quiz-q3","type":"id","q":"The measure of how happy customers are with a service is customer ______.","answer":"satisfaction"},{"id":"housekeeping-common-l3-quiz-q4","type":"mcq","q":"A customer is angry about a delayed order. What should you say first?","options":["That is not our problem.","I understand — let me check the status for you.","You should have ordered earlier.","Call again tomorrow."],"answer":"I understand — let me check the status for you."}]},{"id":"housekeeping-common-l4-quiz","programId":"housekeeping","lessonId":"housekeeping-common-l4","title":"Working with Others & Time Management Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-common-l4-quiz-q1","type":"mcq","q":"Which practice helps a team meet deadlines?","options":["Working without a plan","Setting priorities and tracking tasks","Avoiding updates","Doing everything at the last minute"],"answer":"Setting priorities and tracking tasks"},{"id":"housekeeping-common-l4-quiz-q2","type":"tf","q":"A task list should be reviewed and updated as work progresses.","answer":true},{"id":"housekeeping-common-l4-quiz-q3","type":"id","q":"Arranging tasks from most to least important is called ______.","answer":"prioritizing"},{"id":"housekeeping-common-l4-quiz-q4","type":"mcq","q":"A teammate is behind on a shared task. What is the best action?","options":["Ignore it","Offer help and inform the lead","Complain about it later","Take over without telling anyone"],"answer":"Offer help and inform the lead"}]},{"id":"housekeeping-core-u1-l1-quiz","programId":"housekeeping","lessonId":"housekeeping-core-u1-l1","title":"Introduction to Housekeeping Operations Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-core-u1-l1-quiz-q1","type":"mcq","q":"Housekeeping mainly delivers which guest expectation?","options":["Clean, comfortable rooms","Menu planning","Airline bookings","Building construction"],"answer":"Clean, comfortable rooms"},{"id":"housekeeping-core-u1-l1-quiz-q2","type":"tf","q":"Grooming standards apply to housekeeping staff because they deal with guests.","answer":true},{"id":"housekeeping-core-u1-l1-quiz-q3","type":"id","q":"The department that cleans guest rooms and public areas is ______.","answer":"housekeeping"},{"id":"housekeeping-core-u1-l1-quiz-q4","type":"mcq","q":"Which is a duty of a room attendant?","options":["Preparing payroll","Cleaning and preparing guest rooms","Designing the hotel website","Auditing financial statements"],"answer":"Cleaning and preparing guest rooms"}]},{"id":"housekeeping-core-u1-l2-quiz","programId":"housekeeping","lessonId":"housekeeping-core-u1-l2","title":"Cleaning Equipment & Chemicals Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-core-u1-l2-quiz-q1","type":"mcq","q":"Which tool is used to reach dust on high surfaces?","options":["Mop","Extendable duster","Bucket","Caddie"],"answer":"Extendable duster"},{"id":"housekeeping-core-u1-l2-quiz-q2","type":"tf","q":"Cleaning chemicals should be kept in labeled containers away from food.","answer":true},{"id":"housekeeping-core-u1-l2-quiz-q3","type":"id","q":"The document that explains a chemical's hazards is the Safety Data ______.","answer":"sheet"},{"id":"housekeeping-core-u1-l2-quiz-q4","type":"mcq","q":"Why is correct chemical dilution important?","options":["It makes cleaning slower","It cleans effectively without damaging surfaces","It uses more product","It avoids reading labels"],"answer":"It cleans effectively without damaging surfaces"}]},{"id":"housekeeping-core-u1-l3-quiz","programId":"housekeeping","lessonId":"housekeeping-core-u1-l3","title":"Guest Room Preparation Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-core-u1-l3-quiz-q1","type":"mcq","q":"What is the first step when cleaning a guest room?","options":["Making the bed","Knocking and announcing entry","Cleaning the bathroom","Vacuuming the floor"],"answer":"Knocking and announcing entry"},{"id":"housekeeping-core-u1-l3-quiz-q2","type":"tf","q":"Supplies are replenished before the final inspection of the room.","answer":true},{"id":"housekeeping-core-u1-l3-quiz-q3","type":"id","q":"The last step of room preparation is the final ______.","answer":"inspection"},{"id":"housekeeping-core-u1-l3-quiz-q4","type":"mcq","q":"Which cleaning order is correct?","options":["Bathroom, dusting, bed making","Dusting, bed making, bathroom cleaning","Bed making, dusting, bathroom cleaning","Floor, bathroom, dusting"],"answer":"Dusting, bed making, bathroom cleaning"}]},{"id":"housekeeping-core-u2-l1-quiz","programId":"housekeeping","lessonId":"housekeeping-core-u2-l1","title":"Bed Making Techniques Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-core-u2-l1-quiz-q1","type":"mcq","q":"Triple sheeting uses how many flat sheets?","options":["One","Two","Three","Four"],"answer":"Three"},{"id":"housekeeping-core-u2-l1-quiz-q2","type":"tf","q":"The bed is stripped before fresh linen is applied.","answer":true},{"id":"housekeeping-core-u2-l1-quiz-q3","type":"id","q":"The sheet placed over the mattress and tucked on all sides is the ______ sheet.","answer":"fitted"},{"id":"housekeeping-core-u2-l1-quiz-q4","type":"mcq","q":"How should pillowcases be finished?","options":["Left loose and wrinkled","Smooth, tucked and facing the same way","Placed under the bed","Changed once a week only"],"answer":"Smooth, tucked and facing the same way"}]},{"id":"housekeeping-core-u2-l2-quiz","programId":"housekeeping","lessonId":"housekeeping-core-u2-l2","title":"Linen Room Management Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-core-u2-l2-quiz-q1","type":"mcq","q":"A linen par level is:","options":["The maximum price of linen","The minimum stock kept on hand","The number of laundry staff","The color of the linen"],"answer":"The minimum stock kept on hand"},{"id":"housekeeping-core-u2-l2-quiz-q2","type":"tf","q":"Soiled linen is separated from clean linen immediately.","answer":true},{"id":"housekeeping-core-u2-l2-quiz-q3","type":"id","q":"Linen already used by guests is called ______ linen.","answer":"soiled"},{"id":"housekeeping-core-u2-l2-quiz-q4","type":"mcq","q":"Which practice reduces linen loss?","options":["Recording issues and returns","Storing linen in guest rooms","Loaning linen to staff","Mixing linen with trash"],"answer":"Recording issues and returns"}]},{"id":"housekeeping-core-u3-l1-quiz","programId":"housekeeping","lessonId":"housekeeping-core-u3-l1","title":"Bathroom Cleaning Sequence Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-core-u3-l1-quiz-q1","type":"mcq","q":"Which bathroom area is cleaned first?","options":["Floor","Mirror and sink","Toilet","Shower"],"answer":"Mirror and sink"},{"id":"housekeeping-core-u3-l1-quiz-q2","type":"tf","q":"The same cloth may be used for the toilet and the sink to save time.","answer":false},{"id":"housekeeping-core-u3-l1-quiz-q3","type":"id","q":"Using a separate color-coded cloth per area prevents ______.","answer":"cross-contamination"},{"id":"housekeeping-core-u3-l1-quiz-q4","type":"mcq","q":"Why is the bathroom floor cleaned last?","options":["It dries fastest","So dirt from other surfaces does not fall on it","It is the least dirty","Guests do not see it"],"answer":"So dirt from other surfaces does not fall on it"}]},{"id":"housekeeping-core-u4-l1-quiz","programId":"housekeeping","lessonId":"housekeeping-core-u4-l1","title":"Room Inspection Standards Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"housekeeping-core-u4-l1-quiz-q1","type":"mcq","q":"What is the purpose of a room inspection checklist?","options":["To delay room release","To verify cleanliness and functionality consistently","To record guest complaints only","To order supplies"],"answer":"To verify cleanliness and functionality consistently"},{"id":"housekeeping-core-u4-l1-quiz-q2","type":"tf","q":"Defects found during inspection should be documented and escalated.","answer":true},{"id":"housekeeping-core-u4-l1-quiz-q3","type":"id","q":"Rooms that pass inspection are reported to the front desk as ______ rooms.","answer":"ready"},{"id":"housekeeping-core-u4-l1-quiz-q4","type":"mcq","q":"Which item is checked for functionality during inspection?","options":["TV remote and lights","Guest luggage","Room rate","Menu prices"],"answer":"TV remote and lights"}]}]$q$::jsonb)
  where id = 'housekeeping';

