]},{"id":"hilot-basic-l3-quiz","programId":"hilot","lessonId":"hilot-basic-l3","title":"Basic Digital Literacy Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-basic-l3-quiz-q1","type":"mcq","q":"Which of these is an email application?","options":["Gmail","Excel","Photoshop","VLC"],"answer":"Gmail"},{"id":"hilot-basic-l3-quiz-q2","type":"tf","q":"A strong password should be shared with co-workers so they can open your files.","answer":false},{"id":"hilot-basic-l3-quiz-q3","type":"id","q":"The key combination Ctrl + C is used to ______ the selected text.","answer":"copy"},{"id":"hilot-basic-l3-quiz-q4","type":"mcq","q":"What should you do before opening an attachment from an unknown sender?","options":["Open it immediately","Verify the sender and scan it for malware","Forward it to all staff","Reply with your password"],"answer":"Verify the sender and scan it for malware"}]},{"id":"hilot-basic-l4-quiz","programId":"hilot","lessonId":"hilot-basic-l4","title":"Workplace Behavior & Professionalism Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-basic-l4-quiz-q1","type":"mcq","q":"What does punctuality at work demonstrate?","options":["Reliability and respect for others","That you are overworked","That you dislike the job","Nothing important"],"answer":"Reliability and respect for others"},{"id":"hilot-basic-l4-quiz-q2","type":"tf","q":"Personal social media accounts may be used to discuss confidential client information.","answer":false},{"id":"hilot-basic-l4-quiz-q3","type":"id","q":"The set of rules that guides acceptable behavior in the workplace is the code of ______.","answer":"conduct"},{"id":"hilot-basic-l4-quiz-q4","type":"mcq","q":"A colleague keeps arriving late. What is the professional response?","options":["Post about it online","Raise it with the supervisor privately","Ignore your own work","Confront them in front of clients"],"answer":"Raise it with the supervisor privately"}]},{"id":"hilot-common-l1-quiz","programId":"hilot","lessonId":"hilot-common-l1","title":"Workplace Communication Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-common-l1-quiz-q1","type":"mcq","q":"Which channel is best for reporting an urgent safety incident?","options":["A memo next week","A call or direct message to the supervisor","A suggestion box","A social media post"],"answer":"A call or direct message to the supervisor"},{"id":"hilot-common-l1-quiz-q2","type":"tf","q":"Incident reports should be written as soon as possible after the event.","answer":true},{"id":"hilot-common-l1-quiz-q3","type":"id","q":"The written record of what was discussed in a meeting is called the ______.","answer":"minutes"},{"id":"hilot-common-l1-quiz-q4","type":"mcq","q":"What is the best way to confirm instructions you received verbally?","options":["Assume you understood","Write them down and repeat them back","Wait for a written complaint","Ask a client instead"],"answer":"Write them down and repeat them back"}]},{"id":"hilot-common-l2-quiz","programId":"hilot","lessonId":"hilot-common-l2","title":"Workplace Safety & Emergency Procedures Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-common-l2-quiz-q1","type":"mcq","q":"What does OSH stand for?","options":["Occupational Safety and Health","Office Staff Handbook","Operational Service Hours","Organized Safety Help"],"answer":"Occupational Safety and Health"},{"id":"hilot-common-l2-quiz-q2","type":"tf","q":"Fire exits must be kept clear of boxes and equipment at all times.","answer":true},{"id":"hilot-common-l2-quiz-q3","type":"id","q":"Gear worn to protect a worker from hazards is called ______ equipment.","answer":"personal protective"},{"id":"hilot-common-l2-quiz-q4","type":"mcq","q":"During an earthquake while indoors you should:","options":["Run to the elevator","Duck, cover and hold","Stand near the windows","Call clients first"],"answer":"Duck, cover and hold"}]},{"id":"hilot-common-l3-quiz","programId":"hilot","lessonId":"hilot-common-l3","title":"Customer Service Excellence Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-common-l3-quiz-q1","type":"mcq","q":"What is the first step in handling a customer complaint?","options":["Defend the company","Listen without interrupting","Offer a refund immediately","Blame another staff member"],"answer":"Listen without interrupting"},{"id":"hilot-common-l3-quiz-q2","type":"tf","q":"Customer expectations are met only when the service is free of charge.","answer":false},{"id":"hilot-common-l3-quiz-q3","type":"id","q":"The measure of how happy customers are with a service is customer ______.","answer":"satisfaction"},{"id":"hilot-common-l3-quiz-q4","type":"mcq","q":"A customer is angry about a delayed order. What should you say first?","options":["That is not our problem.","I understand — let me check the status for you.","You should have ordered earlier.","Call again tomorrow."],"answer":"I understand — let me check the status for you."}]},{"id":"hilot-common-l4-quiz","programId":"hilot","lessonId":"hilot-common-l4","title":"Working with Others & Time Management Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-common-l4-quiz-q1","type":"mcq","q":"Which practice helps a team meet deadlines?","options":["Working without a plan","Setting priorities and tracking tasks","Avoiding updates","Doing everything at the last minute"],"answer":"Setting priorities and tracking tasks"},{"id":"hilot-common-l4-quiz-q2","type":"tf","q":"A task list should be reviewed and updated as work progresses.","answer":true},{"id":"hilot-common-l4-quiz-q3","type":"id","q":"Arranging tasks from most to least important is called ______.","answer":"prioritizing"},{"id":"hilot-common-l4-quiz-q4","type":"mcq","q":"A teammate is behind on a shared task. What is the best action?","options":["Ignore it","Offer help and inform the lead","Complain about it later","Take over without telling anyone"],"answer":"Offer help and inform the lead"}]},{"id":"hilot-core-u1-l1-quiz","programId":"hilot","lessonId":"hilot-core-u1-l1","title":"Skeletal & Muscular System Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-core-u1-l1-quiz-q1","type":"mcq","q":"Which system provides the framework and protection for the body?","options":["Skeletal","Digestive","Endocrine","Respiratory"],"answer":"Skeletal"},{"id":"hilot-core-u1-l1-quiz-q2","type":"tf","q":"Muscles work in pairs to move a joint.","answer":true},{"id":"hilot-core-u1-l1-quiz-q3","type":"id","q":"The point where two bones meet is called a ______.","answer":"joint"},{"id":"hilot-core-u1-l1-quiz-q4","type":"mcq","q":"Which muscle group is at the back of the upper arm?","options":["Biceps","Triceps","Deltoid","Pectoral"],"answer":"Triceps"}]},{"id":"hilot-core-u1-l2-quiz","programId":"hilot","lessonId":"hilot-core-u1-l2","title":"Circulatory & Lymphatic Systems Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-core-u1-l2-quiz-q1","type":"mcq","q":"Massage strokes directed toward the heart mainly support:","options":["Bone growth","Venous return and lymph flow","Hair growth","Fat digestion"],"answer":"Venous return and lymph flow"},{"id":"hilot-core-u1-l2-quiz-q2","type":"tf","q":"The lymphatic system helps remove waste and supports immunity.","answer":true},{"id":"hilot-core-u1-l2-quiz-q3","type":"id","q":"The fluid that carries oxygen through the body is ______.","answer":"blood"},{"id":"hilot-core-u1-l2-quiz-q4","type":"mcq","q":"In which direction should effleurage generally be applied?","options":["Away from the heart","Toward the heart","In circles only","In random directions"],"answer":"Toward the heart"}]},{"id":"hilot-core-u2-l1-quiz","programId":"hilot","lessonId":"hilot-core-u2-l1","title":"Introduction to Hilot Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-core-u2-l1-quiz-q1","type":"mcq","q":"Hilot is best described as:","options":["A modern gym workout","A traditional Filipino healing art","A type of surgery","A beauty treatment only"],"answer":"A traditional Filipino healing art"},{"id":"hilot-core-u2-l1-quiz-q2","type":"tf","q":"Hilot has cultural roots in Filipino communities.","answer":true},{"id":"hilot-core-u2-l1-quiz-q3","type":"id","q":"The traditional Filipino healer who practices hilot is the ______.","answer":"manghihilot"},{"id":"hilot-core-u2-l1-quiz-q4","type":"mcq","q":"Modern hilot practice mainly aims to:","options":["Replace medical care","Relieve muscle pain and stress","Perform only spiritual rituals","Sell herbal products"],"answer":"Relieve muscle pain and stress"}]},{"id":"hilot-core-u2-l2-quiz","programId":"hilot","lessonId":"hilot-core-u2-l2","title":"Basic Massage Strokes Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-core-u2-l2-quiz-q1","type":"mcq","q":"Which stroke uses light, gliding movements?","options":["Effleurage","Petrissage","Tapotement","Friction"],"answer":"Effleurage"},{"id":"hilot-core-u2-l2-quiz-q2","type":"tf","q":"Tapotement is a rhythmic percussion stroke.","answer":true},{"id":"hilot-core-u2-l2-quiz-q3","type":"id","q":"Kneading and squeezing of muscle tissue is called ______.","answer":"petrissage"},{"id":"hilot-core-u2-l2-quiz-q4","type":"mcq","q":"How should massage pressure be applied?","options":["Always at maximum","Adjusted to the client's comfort","Only with the elbows","The same for every client"],"answer":"Adjusted to the client's comfort"}]},{"id":"hilot-core-u3-l1-quiz","programId":"hilot","lessonId":"hilot-core-u3-l1","title":"Back, Shoulder & Neck Massage Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-core-u3-l1-quiz-q1","type":"mcq","q":"What must be done before starting a back massage?","options":["Apply oil to the hair","Drape the client and check comfort","Ask the client to stand","Turn up the lights"],"answer":"Drape the client and check comfort"},{"id":"hilot-core-u3-l1-quiz-q2","type":"tf","q":"Strong pressure should be applied directly to the throat during a neck massage.","answer":false},{"id":"hilot-core-u3-l1-quiz-q3","type":"id","q":"Covering the client with a sheet to protect privacy is called ______.","answer":"draping"},{"id":"hilot-core-u3-l1-quiz-q4","type":"mcq","q":"Which area commonly holds tension in office workers?","options":["Shoulders and upper back","Knees","Ankles","Elbows"],"answer":"Shoulders and upper back"}]},{"id":"hilot-core-u3-l2-quiz","programId":"hilot","lessonId":"hilot-core-u3-l2","title":"Limb & Foot Massage Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-core-u3-l2-quiz-q1","type":"mcq","q":"Reflexology focuses on:","options":["Pressure points on the feet","Bone setting","Hair treatment","Skin whitening"],"answer":"Pressure points on the feet"},{"id":"hilot-core-u3-l2-quiz-q2","type":"tf","q":"Limb massage generally follows the direction of blood flow toward the heart.","answer":true},{"id":"hilot-core-u3-l2-quiz-q3","type":"id","q":"Massaging the feet with thumb pressure on specific points is called ______.","answer":"reflexology"},{"id":"hilot-core-u3-l2-quiz-q4","type":"mcq","q":"Which precaution applies to a client with varicose veins?","options":["Deep pressure on the veins","Gentle strokes and medical clearance","Skip massage forever","Use hot stones"],"answer":"Gentle strokes and medical clearance"}]},{"id":"hilot-core-u4-l1-quiz","programId":"hilot","lessonId":"hilot-core-u4-l1","title":"Client Consultation & Contraindications Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"hilot-core-u4-l1-quiz-q1","type":"mcq","q":"Which condition is a contraindication for massage?","options":["Mild stress","Fever or an open skin infection","Muscle stiffness","Desk work"],"answer":"Fever or an open skin infection"},{"id":"hilot-core-u4-l1-quiz-q2","type":"tf","q":"Informed consent is obtained before the session begins.","answer":true},{"id":"hilot-core-u4-l1-quiz-q3","type":"id","q":"A condition in which massage must be avoided is called a ______.","answer":"contraindication"},{"id":"hilot-core-u4-l1-quiz-q4","type":"mcq","q":"The main purpose of the intake consultation is to:","options":["Sell products","Understand the client's needs and health risks","Shorten the session","Replace the therapist"],"answer":"Understand the client's needs and health risks"}]}]$q$::jsonb)
  where id = 'hilot';

