1-q10","type":"tf","q":"Limb massage generally follows the direction of blood flow toward the heart.","answer":true}],"questionCount":10,"timeLimit":60,"passing":75,"date":"2026-12-01","status":"Upcoming","published":true}]$q$::jsonb)
