ng-common-l2-quiz-q4","type":"mcq","q":"During an earthquake while indoors you should:","options":["Run to the elevator","Duck, cover and hold","Stand near the windows","Call clients first"],"answer":"Duck, cover and hold"}]},{"id":"bookkeeping-common-l3-quiz","programId":"bookkeeping","lessonId":"bookkeeping-common-l3","title":"Customer Service Excellence Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-common-l3-quiz-q1","type":"mcq","q":"What is the first step in handling a customer complaint?","options":["Defend the company","Listen without interrupting","Offer a refund immediately","Blame another staff member"],"answer":"Listen without interrupting"},{"id":"bookkeeping-common-l3-quiz-q2","type":"tf","q":"Customer expectations are met only when the service is free of charge.","answer":false},{"id":"bookkeeping-common-l3-quiz-q3","type":"id","q":"The measure of how happy customers are with a service is customer ______.","answer":"satisfaction"},{"id":"bookkeeping-common-l3-quiz-q4","type":"mcq","q":"A customer is angry about a delayed order. What should you say first?","options":["That is not our problem.","I understand — let me check the status for you.","You should have ordered earlier.","Call again tomorrow."],"answer":"I understand — let me check the status for you."}]},{"id":"bookkeeping-common-l4-quiz","programId":"bookkeeping","lessonId":"bookkeeping-common-l4","title":"Working with Others & Time Management Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-common-l4-quiz-q1","type":"mcq","q":"Which practice helps a team meet deadlines?","options":["Working without a plan","Setting priorities and tracking tasks","Avoiding updates","Doing everything at the last minute"],"answer":"Setting priorities and tracking tasks"},{"id":"bookkeeping-common-l4-quiz-q2","type":"tf","q":"A task list should be reviewed and updated as work progresses.","answer":true},{"id":"bookkeeping-common-l4-quiz-q3","type":"id","q":"Arranging tasks from most to least important is called ______.","answer":"prioritizing"},{"id":"bookkeeping-common-l4-quiz-q4","type":"mcq","q":"A teammate is behind on a shared task. What is the best action?","options":["Ignore it","Offer help and inform the lead","Complain about it later","Take over without telling anyone"],"answer":"Offer help and inform the lead"}]},{"id":"bookkeeping-core-u1-l1-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u1-l1","title":"Introduction to Bookkeeping & Accounting Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u1-l1-quiz-q1","type":"mcq","q":"Bookkeeping is best described as:","options":["The systematic recording of business transactions","Auditing financial statements","Managing investments","Filing tax returns only"],"answer":"The systematic recording of business transactions"},{"id":"bookkeeping-core-u1-l1-quiz-q2","type":"tf","q":"Accounting is broader than bookkeeping because it includes analysis and reporting.","answer":true},{"id":"bookkeeping-core-u1-l1-quiz-q3","type":"id","q":"The sequence of steps from transaction to financial statements is the accounting ______.","answer":"cycle"},{"id":"bookkeeping-core-u1-l1-quiz-q4","type":"mcq","q":"Who uses financial information?","options":["The owner only","Owners, lenders, government and investors","Auditors only","Customers only"],"answer":"Owners, lenders, government and investors"}]},{"id":"bookkeeping-core-u1-l2-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u1-l2","title":"The Accounting Equation & Double-Entry System Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u1-l2-quiz-q1","type":"mcq","q":"The accounting equation is:","options":["Assets = Liabilities + Equity","Assets = Equity - Liabilities","Equity = Assets + Liabilities","Liabilities = Assets + Equity"],"answer":"Assets = Liabilities + Equity"},{"id":"bookkeeping-core-u1-l2-quiz-q2","type":"tf","q":"Every transaction affects at least two accounts.","answer":true},{"id":"bookkeeping-core-u1-l2-quiz-q3","type":"id","q":"Increases in assets are recorded as ______.","answer":"debits"},{"id":"bookkeeping-core-u1-l2-quiz-q4","type":"mcq","q":"A debit increases which account?","options":["Revenue","Expense","Liability","Equity"],"answer":"Expense"}]},{"id":"bookkeeping-core-u1-l3-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u1-l3","title":"Accounting Concepts & the Accounting Cycle Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u1-l3-quiz-q1","type":"mcq","q":"Under the accrual concept, revenue is recorded when:","options":["Cash is received","It is earned","The year ends","The customer requests it"],"answer":"It is earned"},{"id":"bookkeeping-core-u1-l3-quiz-q2","type":"tf","q":"The going concern assumption means the business is expected to keep operating.","answer":true},{"id":"bookkeeping-core-u1-l3-quiz-q3","type":"id","q":"Matching expenses with the revenue they helped earn is the ______ principle.","answer":"matching"},{"id":"bookkeeping-core-u1-l3-quiz-q4","type":"mcq","q":"Which is the last step of the accounting cycle?","options":["Journalizing","Posting","Preparing the trial balance","Closing the books"],"answer":"Closing the books"}]},{"id":"bookkeeping-core-u2-l1-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u2-l1","title":"Source Documents & the Chart of Accounts Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u2-l1-quiz-q1","type":"mcq","q":"Which document proves a sale on credit?","options":["Sales invoice","Bank statement","Payroll register","Petty cash voucher"],"answer":"Sales invoice"},{"id":"bookkeeping-core-u2-l1-quiz-q2","type":"tf","q":"The chart of accounts lists every account the business uses.","answer":true},{"id":"bookkeeping-core-u2-l1-quiz-q3","type":"id","q":"The document a seller issues to a buyer for goods delivered is an ______.","answer":"invoice"},{"id":"bookkeeping-core-u2-l1-quiz-q4","type":"mcq","q":"Why must source documents be verified?","options":["To ensure accuracy and legitimacy","To increase sales","To delay recording","To replace the ledger"],"answer":"To ensure accuracy and legitimacy"}]},{"id":"bookkeeping-core-u2-l2-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u2-l2","title":"Journalizing in the General Journal Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u2-l2-quiz-q1","type":"mcq","q":"In what order does the general journal record transactions?","options":["Alphabetical","Chronological","By amount","By account number"],"answer":"Chronological"},{"id":"bookkeeping-core-u2-l2-quiz-q2","type":"tf","q":"The debit entry is written before the credit entry in a journal.","answer":true},{"id":"bookkeeping-core-u2-l2-quiz-q3","type":"id","q":"A journal entry with more than one debit or credit is a ______ entry.","answer":"compound"},{"id":"bookkeeping-core-u2-l2-quiz-q4","type":"mcq","q":"Which details belong in a journal entry?","options":["Date, accounts, amounts and explanation","The amount only","The account title only","The date only"],"answer":"Date, accounts, amounts and explanation"}]},{"id":"bookkeeping-core-u2-l3-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u2-l3","title":"Special Journals & Subsidiary Ledgers Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u2-l3-quiz-q1","type":"mcq","q":"Which special journal records sales on account?","options":["Sales journal","Cash receipts journal","Purchases journal","General journal"],"answer":"Sales journal"},{"id":"bookkeeping-core-u2-l3-quiz-q2","type":"tf","q":"Subsidiary ledgers show the balance of each individual customer or supplier.","answer":true},{"id":"bookkeeping-core-u2-l3-quiz-q3","type":"id","q":"The ledger summarizing all customer accounts receivable is the ______ ledger.","answer":"subsidiary"},{"id":"bookkeeping-core-u2-l3-quiz-q4","type":"mcq","q":"Special journals are used mainly to:","options":["Handle high volumes of similar transactions","Replace the trial balance","Record adjusting entries","Compute payroll tax"],"answer":"Handle high volumes of similar transactions"}]},{"id":"bookkeeping-core-u3-l1-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u3-l1","title":"Posting to the General Ledger Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u3-l1-quiz-q1","type":"mcq","q":"Posting means transferring entries from:","options":["The journal to the ledger","The ledger to the journal","The trial balance to the journal","The bank to the books"],"answer":"The journal to the ledger"},{"id":"bookkeeping-core-u3-l1-quiz-q2","type":"tf","q":"Each ledger account keeps a running balance.","answer":true},{"id":"bookkeeping-core-u3-l1-quiz-q3","type":"id","q":"The journal page number written in the ledger is the ______ reference.","answer":"folio"},{"id":"bookkeeping-core-u3-l1-quiz-q4","type":"mcq","q":"What is posted to the ledger for each entry?","options":["The total only","The date, amount and journal reference","The account title only","The explanation only"],"answer":"The date, amount and journal reference"}]},{"id":"bookkeeping-core-u3-l2-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u3-l2","title":"Preparing the Trial Balance Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u3-l2-quiz-q1","type":"mcq","q":"A trial balance lists:","options":["Every account and its balance","Revenue accounts only","Cash transactions only","The chart of accounts"],"answer":"Every account and its balance"},{"id":"bookkeeping-core-u3-l2-quiz-q2","type":"tf","q":"If a trial balance does not balance, an error definitely exists.","answer":true},{"id":"bookkeeping-core-u3-l2-quiz-q3","type":"id","q":"The trial balance prepared before adjustments is the ______ trial balance.","answer":"unadjusted"},{"id":"bookkeeping-core-u3-l2-quiz-q4","type":"mcq","q":"Which technique helps locate trial balance errors?","options":["Recomputing balances and tracing postings","Ignoring the difference","Deleting entries","Changing the fiscal year"],"answer":"Recomputing balances and tracing postings"}]},{"id":"bookkeeping-core-u3-l3-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u3-l3","title":"Adjusting Entries & the Worksheet Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u3-l3-quiz-q1","type":"mcq","q":"Which of these is an adjusting entry?","options":["Recording depreciation for the period","Recording a cash sale","Paying a supplier","Opening a bank account"],"answer":"Recording depreciation for the period"},{"id":"bookkeeping-core-u3-l3-quiz-q2","type":"tf","q":"Unearned revenue is a liability until the service is performed.","answer":true},{"id":"bookkeeping-core-u3-l3-quiz-q3","type":"id","q":"Expenses already incurred but not yet paid are accrued ______.","answer":"expenses"},{"id":"bookkeeping-core-u3-l3-quiz-q4","type":"mcq","q":"The worksheet is used to produce which output?","options":["The adjusted trial balance","The bank statement","The payroll register","The purchase order"],"answer":"The adjusted trial balance"}]},{"id":"bookkeeping-core-u4-l1-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u4-l1","title":"Preparing the Income Statement Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u4-l1-quiz-q1","type":"mcq","q":"Gross profit equals:","options":["Net sales - cost of goods sold","Net sales - operating expenses","Revenue + expenses","Assets - liabilities"],"answer":"Net sales - cost of goods sold"},{"id":"bookkeeping-core-u4-l1-quiz-q2","type":"tf","q":"A multi-step income statement separates operating from non-operating items.","answer":true},{"id":"bookkeeping-core-u4-l1-quiz-q3","type":"id","q":"The profit left after all expenses are deducted is ______ income.","answer":"net"},{"id":"bookkeeping-core-u4-l1-quiz-q4","type":"mcq","q":"Which account appears on the income statement?","options":["Service revenue","Accounts receivable","Owner's capital","Equipment"],"answer":"Service revenue"}]},{"id":"bookkeeping-core-u4-l2-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u4-l2","title":"Preparing the Statement of Financial Position Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u4-l2-quiz-q1","type":"mcq","q":"Which of these is a current asset?","options":["Cash","Building","Equipment","Patent"],"answer":"Cash"},{"id":"bookkeeping-core-u4-l2-quiz-q2","type":"tf","q":"The statement of financial position reports assets, liabilities and equity at a point in time.","answer":true},{"id":"bookkeeping-core-u4-l2-quiz-q3","type":"id","q":"Assets minus liabilities equals ______.","answer":"equity"},{"id":"bookkeeping-core-u4-l2-quiz-q4","type":"mcq","q":"Which item is a non-current liability?","options":["Loan payable after five years","Accounts payable","Accrued wages","Prepaid rent"],"answer":"Loan payable after five years"}]},{"id":"bookkeeping-core-u4-l3-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u4-l3","title":"Bank Reconciliation & Internal Control Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u4-l3-quiz-q1","type":"mcq","q":"A deposit in transit is:","options":["Recorded in the books but not yet on the bank statement","A bank error","An outstanding check","A service charge"],"answer":"Recorded in the books but not yet on the bank statement"},{"id":"bookkeeping-core-u4-l3-quiz-q2","type":"tf","q":"Outstanding checks are deducted from the bank balance in a reconciliation.","answer":true},{"id":"bookkeeping-core-u4-l3-quiz-q3","type":"id","q":"Separating duties among employees is a form of internal ______.","answer":"control"},{"id":"bookkeeping-core-u4-l3-quiz-q4","type":"mcq","q":"Which is a good internal control for cash?","options":["One person handles and records all cash","Segregation of duties and regular reconciliation","No documentation","An annual audit only"],"answer":"Segregation of duties and regular reconciliation"}]},{"id":"bookkeeping-core-u4-l4-quiz","programId":"bookkeeping","lessonId":"bookkeeping-core-u4-l4","title":"Payroll, Taxes & Record Keeping Quiz","passing":75,"timeLimit":15,"published":true,"questions":[{"id":"bookkeeping-core-u4-l4-quiz-q1","type":"mcq","q":"Net pay equals:","options":["Gross pay minus deductions","Gross pay plus deductions","Gross pay only","Deductions minus gross pay"],"answer":"Gross pay minus deductions"},{"id":"bookkeeping-core-u4-l4-quiz-q2","type":"tf","q":"Business records must be kept for the period required by law.","answer":true},{"id":"bookkeeping-core-u4-l4-quiz-q3","type":"id","q":"Deductions required by law such as SSS and PhilHealth are ______ deductions.","answer":"statutory"},{"id":"bookkeeping-core-u4-l4-quiz-q4","type":"mcq","q":"Which document supports the payroll entries?","options":["Payroll register","Sales invoice","Bank statement","Delivery receipt"],"answer":"Payroll register"}]}]$q$::jsonb)
  where id = 'bookkeeping';

